PREFIX gleif-L1: <https://www.gleif.org/ontology/L1/>
PREFIX gleif-base: <https://www.gleif.org/ontology/Base/>
PREFIX gleif-re: <https://www.gleif.org/ontology/ReportingException/>
PREFIX kgx: <https://example.org/gleif-kg/ontology/>
PREFIX lei: <https://www.gleif.org/data/lei/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?parent ?exceptionReference ?exceptionReason WHERE {
  # Find the entity with legal name "M-M FRANCE"
  ?e rdfs:label "M-M FRANCE" .

  OPTIONAL { ?e kgx:hasUltimateConsolidationParent ?parent . }

  OPTIONAL {
    ?reglei gleif-re:hasReportingEntity ?e ;
            gleif-re:hasExceptionReference ?exceptionReference ;
            gleif-re:hasExceptionReason ?exceptionReason .
  }
}

