PREFIX gleif-L1: <https://www.gleif.org/ontology/L1/>
PREFIX kgx: <https://example.org/gleif-kg/ontology/>

SELECT ?branchLegalName WHERE {
  # Find the entity whose legal name is THE ONELIFE COMPANY S.A.
  ?headOffice gleif-L1:hasLegalName "THE ONELIFE COMPANY S.A." .

  # Find branches that have this head office as their parent
  ?branch kgx:hasBranchParent ?headOffice ;
          gleif-L1:hasLegalName ?branchLegalName .
}

PREFIX gleif-L1: <https://www.gleif.org/ontology/L1/>
PREFIX gleif-base: <https://www.gleif.org/ontology/Base/>
PREFIX kgx: <https://example.org/gleif-kg/ontology/>
PREFIX jur: <https://www.gleif.org/data/jurisdiction/>

SELECT (COUNT(DISTINCT ?e) AS ?count)
WHERE {
  ?e gleif-base:hasLegalJurisdiction jur:FR .
  OPTIONAL { ?e kgx:hasUltimateConsolidationParent ?parent . }
  FILTER (!BOUND(?parent))
}

PREFIX kgx: <https://example.org/gleif-kg/ontology/>

SELECT (COUNT(?e) AS ?count)
WHERE {
  ?e kgx:hasFundManager ?manager .
  FILTER NOT EXISTS { ?e kgx:hasUmbrellaFund ?umbrella }
}

SELECT ?reason (COUNT(?entity) AS ?count)
WHERE {
  FILTER(false)
}
GROUP BY ?reason

PREFIX gleif-L1: <https://www.gleif.org/ontology/L1/>
PREFIX gleif-base: <https://www.gleif.org/ontology/Base/>
PREFIX kgx: <https://example.org/gleif-kg/ontology/>
PREFIX gleif-re: <https://www.gleif.org/ontology/ReportingException/>

SELECT ?parent ?exceptionReason
WHERE {
  ?e gleif-L1:hasLegalName "DENTONS INVESTMENT SERVICES LIMITED" .
  OPTIONAL { ?e kgx:hasDirectConsolidationParent ?parent . }
  OPTIONAL {
    ?re gleif-re:hasReportingEntity ?e ;
        gleif-re:hasExceptionReason ?exceptionReason .
  }
  FILTER (BOUND(?parent) || BOUND(?exceptionReason))
}

PREFIX gleif-L1: <https://www.gleif.org/ontology/L1/>
PREFIX lei: <https://www.gleif.org/data/lei/>

SELECT ?legalName WHERE {
  lei:00000000000000000000 gleif-L1:hasLegalName ?legalName .
}
